shaders.source:
struct Uniforms {
  mvp : mat4x4<f32>,
  normalMatrix : mat3x3<f32>,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

struct VertexInput {
  @location(0) rect : vec4<f32>,
  @location(1) tone : vec4<f32>,
  @location(2) region : i32,
};

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) vTone : vec4<f32>,
  @location(1) @interpolate(flat) vRegion : i32,
};

@vertex
fn vertexMain(@builtin(vertex_index) vertexIndex : u32, @builtin(instance_index) instanceIndex : u32, in : VertexInput) -> VertexOutput {
  var out : VertexOutput;
  let corner = vec2<f32>(f32((vertexIndex & 1u)), f32((vertexIndex >> 1u)));
  let p = (in.rect.xy + (corner * in.rect.zw));
  let stripe = (1.0 - (0.04 * f32((instanceIndex & 3u))));
  out.vTone = vec4<f32>((in.tone.rgb * stripe), in.tone.a);
  out.vRegion = in.region;
  out.position = (u.mvp * vec4<f32>(p, 0.0, 1.0));
  return out;
}

@fragment
fn fragmentMain(in : VertexOutput) -> @location(0) vec4<f32> {
  let column = f32((in.vRegion & 3i));
  let lift = (0.25 * column);
  return vec4<f32>(vec3<f32>((in.vTone.r + lift), in.vTone.g, in.vTone.b), 1.0);
}

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
  float4x4 mvp;
  float3x3 normalMatrix;
};

struct VertexIn {
  float4 rect [[attribute(0)]];
  float4 tone [[attribute(1)]];
  int region [[attribute(2)]];
};

struct VertexOut {
  float4 position [[position]];
  float4 vTone;
  int vRegion [[flat]];
};

vertex VertexOut vertexMain(uint vertexIndex [[vertex_id]], uint instanceIndex [[instance_id]], VertexIn in [[stage_in]], constant Uniforms& u [[buffer(0)]]) {
  VertexOut out;
  float2 corner = float2(float((vertexIndex & 1u)), float((vertexIndex >> 1u)));
  float2 p = (in.rect.xy + (corner * in.rect.zw));
  float stripe = (1.0 - (0.04 * float((instanceIndex & 3u))));
  out.vTone = float4((in.tone.rgb * stripe), in.tone.a);
  out.vRegion = in.region;
  out.position = (u.mvp * float4(p, 0.0, 1.0));
  return out;
}

fragment float4 fragmentMain(VertexOut in [[stage_in]], constant Uniforms& u [[buffer(0)]]) {
  float column = float((in.vRegion & 3));
  float lift = (0.25 * column);
  return float4(float3((in.vTone.r + lift), in.vTone.g, in.vTone.b), 1.0);
}

shaders.vertex:
#version 300 es
in vec4 rect;
in vec4 tone;
in int region;
uniform mat4 mvp;
uniform mat3 normalMatrix;
out vec4 vTone;
flat out int vRegion;

void main() {
  uint vertexIndex = uint(gl_VertexID);
  uint instanceIndex = uint(gl_InstanceID);
  vec2 corner = vec2(float((vertexIndex & 1u)), float((vertexIndex >> 1u)));
  vec2 p = (rect.xy + (corner * rect.zw));
  float stripe = (1.0 - (0.04 * float((instanceIndex & 3u))));
  vTone = vec4((tone.rgb * stripe), tone.a);
  vRegion = region;
  gl_Position = (mvp * vec4(p, 0.0, 1.0));
}

shaders.fragment:
#version 300 es
precision highp float;
precision highp int;
uniform mat4 mvp;
uniform mat3 normalMatrix;
in vec4 vTone;
flat in int vRegion;
out vec4 fragColor;

void main() {
  float column = float((vRegion & 3));
  float lift = (0.25 * column);
  fragColor = vec4(vec3((vTone.r + lift), vTone.g, vTone.b), 1.0);
}
